class Solution { private fun solve(nums:IntArray,target:Int):Int{val n=nums.size;val dp=Array(n){IntArray(n)};for(length in 2..n){for(left in 0..n-length){val right=left+length-1;var best=0;if(nums[left]+nums[left+1]==target)best=maxOf(best,1+if(length==2)0 else dp[left+2][right]);if(nums[right-1]+nums[right]==target)best=maxOf(best,1+if(length==2)0 else dp[left][right-2]);if(nums[left]+nums[right]==target)best=maxOf(best,1+if(length==2)0 else dp[left+1][right-1]);dp[left][right]=best}};return dp[0][n-1]}fun maxOperations(nums:IntArray):Int{val n=nums.size;var answer=solve(nums,nums[0]+nums[1]);answer=maxOf(answer,solve(nums,nums[n-2]+nums[n-1]));return maxOf(answer,solve(nums,nums[0]+nums[n-1]))} }
